(733984, 78506, 7322, '<td valign="top">Nice color but a bit flat in temrs of detail.</td>', 'Nice color but a bit flat in temrs of detail.', '2004-05-24 16:51:19.000000', NULL, 1),
(733985, 78909, 7322, '<td valign="top">Interesting color contrast but this composition doesn''t appeal to me.</td>', 'Interesting color contrast but this composition doesn''t appeal to me.', '2004-05-24 16:51:58.000000', NULL, 1),
