(735742, 78525, 20779, '<td valign="top">One of the simplist and most exquisite in the challenge. One of my top 4.</td>', 'One of the simplist and most exquisite in the challenge. One of my top 4.', '2004-05-25 19:36:51.000000', NULL, 1),
(735746, 78448, 20779, '<td valign="top">You did a brilliant job on this one. Great color, crisp and clean focus, very amusing. Just wondering -- is the center one a "real" piece of fruit or not? One of my top four picks this time.</td>', 'You did a brilliant job on this one. Great color, crisp and clean focus, very amusing. Just wondering -- is the center one a "real" piece of fruit or not? One of my top four picks this time.', '2004-05-25 19:38:18.000000', NULL, 1),
(735747, 78573, 20779, '<td valign="top">Was surprised not to see more slipping! Great shot and probably know who did it.</td>', 'Was surprised not to see more slipping! Great shot and probably know who did it.', '2004-05-25 19:39:07.000000', NULL, 1),
(735750, 78593, 20779, '<td valign="top">I got a good laugh out of this one! Love it. I scored it high; could probably be a ten with "perfect" focus.</td>', 'I got a good laugh out of this one! Love it. I scored it high; could probably be a ten with "perfect" focus.', '2004-05-25 19:40:02.000000', NULL, 1),
