(738771, 78497, 18552, '<td valign="top">Cute idea for the challenge.</td>', 'Cute idea for the challenge.', '2004-05-27 04:04:54.000000', NULL, 1),
(738772, 78575, 18552, '<td valign="top">Exceptionally well done banana macro. The colors and focus are great.</td>', 'Exceptionally well done banana macro. The colors and focus are great.', '2004-05-27 04:05:56.000000', NULL, 1),
(738774, 78513, 18552, '<td valign="top">Very interesting picture. At first I couldn''t tell it was a dog biting a banana. To me, it is cropped too closely, if more of the dog were showing it would be a much more enjoyable picture.</td>', 'Very interesting picture. At first I couldn''t tell it was a dog biting a banana. To me, it is cropped too closely, if more of the dog were showing it would be a much more enjoyable picture.', '2004-05-27 04:09:48.000000', NULL, 1),
(738775, 78506, 18552, '<td valign="top">Interesting and unusual take on a sliced banana; it almost looks like sliced cucumber.</td>', 'Interesting and unusual take on a sliced banana; it almost looks like sliced cucumber.', '2004-05-27 04:11:01.000000', NULL, 1),
(738776, 78535, 18552, '<td valign="top">Good, simple idea for the challenge. I think it would have been a more interesting angle if the bananas had been turned more towards the camera. The black background looks too close too the subject and gets too much flash reflection.</td>', 'Good, simple idea for the challenge. I think it would have been a more interesting angle if the bananas had been turned more towards the camera. The black background looks too close too the subject and gets too much flash reflection.', '2004-05-27 04:12:54.000000', NULL, 1),
(738777, 78673, 18552, '<td valign="top">The flower is lovely and well position in the picture; however, the bananas are all slimy looking which really distracts from the whole thing.</td>', 'The flower is lovely and well position in the picture; however, the bananas are all slimy looking which really distracts from the whole thing.', '2004-05-27 04:14:12.000000', NULL, 1),
(738778, 78795, 18552, '<td valign="top">Very nice banana still life; the background is very effective.  To my eye, I think it would have been better with 3 bananas - that is kind of nitpicking but I keep wanting to see another banana there! I guess it''s like gardening, you always plant in groups of three so it will be soothing to the eye.</td>', 'Very nice banana still life; the background is very effective.  To my eye, I think it would have been better with 3 bananas - that is kind of nitpicking but I keep wanting to see another banana there! I guess it''s like gardening, you always plant in groups of three so it will be soothing to the eye.', '2004-05-27 04:17:03.000000', NULL, 1),
(738780, 78910, 18552, '<td valign="top">Great fly macro. How on earth do you get a fly to cooperate with you a as a model!</td>', 'Great fly macro. How on earth do you get a fly to cooperate with you a as a model!', '2004-05-27 04:17:45.000000', NULL, 1),
(738816, 78685, 10170, '<td valign="top">Lots of fun, and good use of desaturation.</td>', 'Lots of fun, and good use of desaturation.', '2004-05-27 05:58:21.000000', NULL, 1),
