(746954, 78544, 10985, '<td valign="top">You can always iron the sheet in post-processing. I do it all the time and it''s really effective! Clone stamp, about 50-60% opacity.</td>', 'You can always iron the sheet in post-processing. I do it all the time and it''s really effective! Clone stamp, about 50-60% opacity.', '2004-06-02 10:10:54.000000', NULL, 0),
(747004, 78466, 5391, '<td valign="top">This was one of my only 10''s.  I''m shocked that it didn''t do better.  Please make a print available, I''d love this on my wall.</td>', 'This was one of my only 10''s.  I''m shocked that it didn''t do better.  Please make a print available, I''d love this on my wall.', '2004-06-02 11:08:04.000000', NULL, 0),
